def transform(grid):
    out=[row[:] for row in grid]
    # Reverse the color order of the nested bands in each object.
    regions=[(1,9,1,10,{3:4,6:1,1:6,4:3}),
             (4,9,13,18,{5:8,4:4,8:5}),
             (11,19,3,15,{6:3,8:4,2:2,4:8,3:6})]
    for r0,r1,c0,c1,mapping in regions:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                out[r][c]=mapping.get(grid[r][c],grid[r][c])
    return out
